import{_ as e,o as r,c as t,a6 as o}from"./chunks/framework.DNkVJs23.js";const u=JSON.parse('{"title":"隐私政策","description":"苍蓝星图鉴应用与网站的隐私政策，说明本地数据、设备备份、邮件联系、数据保留与删除方式。","frontmatter":{"description":"苍蓝星图鉴应用与网站的隐私政策，说明本地数据、设备备份、邮件联系、数据保留与删除方式。","head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hans/privacy/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hans/privacy/"}],["meta",{"property":"og:title","content":"隐私政策 | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"苍蓝星图鉴应用与网站的隐私政策，说明本地数据、设备备份、邮件联系、数据保留与删除方式。"}]]},"headers":[],"relativePath":"zh-hans/privacy/index.md","filePath":"zh-hans/privacy/index.md"}'),i={name:"zh-hans/privacy/index.md"};function n(l,a,h,p,s,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="隐私政策" tabindex="-1">隐私政策 <a class="header-anchor" href="#隐私政策" aria-label="Permalink to &quot;隐私政策&quot;">​</a></h1><p>生效日期：2026 年 10 月 31 日<br> 更新日期：2026 年 11 月 10 日（补充自愿赞助的支付信息说明）</p><p>本政策适用于苍蓝星图鉴（Sapphire Star Codex）的 iOS、Android 与鸿蒙版应用，以及本网站。开发者为 <strong>eurekaffeine（刘耀晨）</strong>。如有隐私相关问题，请联系 <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>。</p><p>应用目前处于开发阶段，各平台的功能可能有所不同。以下说明当前应用与网站的数据处理方式。使用应用无需注册账号。</p><h2 id="本地数据" tabindex="-1">本地数据 <a class="header-anchor" href="#本地数据" aria-label="Permalink to &quot;本地数据&quot;">​</a></h2><p>应用为保留设置并提供相关功能，会在设备上保存数据。根据所使用的平台与功能，可能包括：</p><ul><li>游戏、语言、外观等设置。</li><li>搜索记录与用于恢复浏览位置的页面状态。</li><li>收藏的怪物、装备等资料。</li><li>保存的配装、自定义配装名称、装饰品数量、护石和防具库存。</li></ul><p>这些数据用于资料浏览、搜索、收藏与配装。应用不会将其上传给开发者，开发者也未运营账号或云同步服务。</p><h2 id="权限与自动收集" tabindex="-1">权限与自动收集 <a class="header-anchor" href="#权限与自动收集" aria-label="Permalink to &quot;权限与自动收集&quot;">​</a></h2><p>当前应用未集成广告、追踪、使用统计或自动上传崩溃报告的 SDK。现有功能无需访问通讯录、位置、相机、麦克风或相册，也不收集广告标识符。</p><p>操作系统与应用商店可能根据各自的设置与政策，独立处理安装或诊断信息。平台提供给开发者的诊断信息仅用于排查应用问题。</p><h2 id="邮件联系" tabindex="-1">邮件联系 <a class="header-anchor" href="#邮件联系" aria-label="Permalink to &quot;邮件联系&quot;">​</a></h2><p>通过电子邮件联系开发者时，开发者会收到您的邮箱地址、邮件内容及主动提供的附件。这些信息仅用于回复、排查问题与处理隐私请求，不用于广告或营销邮件。请仅提供处理问题所需的信息。</p><h2 id="网站、备份和其他服务" tabindex="-1">网站、备份和其他服务 <a class="header-anchor" href="#网站、备份和其他服务" aria-label="Permalink to &quot;网站、备份和其他服务&quot;">​</a></h2><p><strong>网站托管。</strong> 本网站由 GitHub Pages 托管，未添加访问统计、广告 Cookie 或追踪像素。站内搜索在浏览器中执行，显示与搜索偏好也可能保存在浏览器中。访问网站时，GitHub 会接收 IP 地址、浏览器信息等技术请求信息，具体处理方式请参阅 <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">GitHub 隐私声明</a>。</p><p><strong>自愿赞助。</strong> 如您选择通过支付宝或微信支付支持开发者，付款由相应平台依其条款与隐私政策处理。本网站仅展示静态收款二维码，不嵌入支付 SDK，也不会接收支付凭据。开发者可能查看支付平台向收款方提供的交易信息，例如金额、时间、付款人显示名称与付款备注。这些记录用于核对赞助款项和处理付款问题，并按支付平台的管理规则及适用的记录保留要求保留。</p><p><strong>设备备份。</strong> 根据系统设置，应用数据可能包含在设备备份或云备份中。备份由相应的平台服务商管理，开发者无法代为读取或删除。</p><p><strong>邮件与外部链接。</strong> 开发者使用 Gmail 接收邮件，Google 根据 <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google 隐私政策</a>处理提供邮件服务所需的信息。访问外部网站或应用商店时，适用相应服务的隐私政策。网站托管、邮件与备份服务商可能在您所在国家或地区以外处理信息。</p><h2 id="数据共享、保留与删除" tabindex="-1">数据共享、保留与删除 <a class="header-anchor" href="#数据共享、保留与删除" aria-label="Permalink to &quot;数据共享、保留与删除&quot;">​</a></h2><p>开发者不会出售、出租个人信息，也不会为广告目的共享个人信息。联系邮件由上述邮件服务商处理。在法律要求或您明确提出相应请求时，开发者可能提供其实际持有的信息。</p><ul><li><strong>应用数据：</strong> 可通过应用现有的删除功能或设备设置清理。清理本地数据时，请选择同时删除应用与数据的选项。保留数据的卸载或归档方式不会清除本地资料。备份需单独管理，重新安装时也可能恢复备份数据。</li><li><strong>网站偏好：</strong> 保存在浏览器中，直至您清除本网站的数据或浏览器自动清理。</li><li><strong>邮件与主动提供的诊断信息：</strong> 仅在处理问题、后续跟进或履行法律义务所需的期间保留。您可请求删除已提供的信息，法律要求保留的情况除外。</li><li><strong>服务商持有的数据：</strong> 包括备份与网站访问日志，由服务商依其规则保留与管理。</li></ul><p>如需查阅、更正或删除已向开发者提供的信息，请通过下方邮箱联系。仅保存在设备上的记录，开发者无法远程读取或删除。</p><h2 id="数据安全" tabindex="-1">数据安全 <a class="header-anchor" href="#数据安全" aria-label="Permalink to &quot;数据安全&quot;">​</a></h2><p>本地数据受操作系统提供的应用存储机制保护。本网站使用 HTTPS。开发者仅为处理支持与隐私请求而访问相关邮件，并使用邮件服务商提供的安全措施。</p><h2 id="儿童和未成年人的隐私" tabindex="-1">儿童和未成年人的隐私 <a class="header-anchor" href="#儿童和未成年人的隐私" aria-label="Permalink to &quot;儿童和未成年人的隐私&quot;">​</a></h2><p>使用应用无需填写个人资料或出生日期，开发者不会有意向儿童收集个人信息。如家长或监护人认为儿童曾向开发者提供个人信息，请联系开发者处理删除事宜。</p><h2 id="政策更新" tabindex="-1">政策更新 <a class="header-anchor" href="#政策更新" aria-label="Permalink to &quot;政策更新&quot;">​</a></h2><p>数据处理方式变更时，本政策与更新日期将相应调整。重要变更将通过网站或应用更新说明告知。新功能如需另行申请权限或取得同意，将在相应操作时提出；本政策本身不构成对相关操作的授权或同意。</p><h2 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to &quot;联系我们&quot;">​</a></h2><p>开发者：<strong>eurekaffeine（刘耀晨）</strong><br> 应用：<strong>苍蓝星图鉴 / Sapphire Star Codex</strong><br> 邮箱：<a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a></p>',30)])])}const g=e(i,[["render",n]]);export{u as __pageData,g as default};
